        ["Mix 1–1,000 tracks."] = "Mezcle de 1 a 1 000 pistas.", ["Mix 2–16 local sources."] = "Mezcle de 2 a 16 fuentes locales.", ["Mix up to 16 sources."] = "Mezcle hasta 16 fuentes.", ["Mixing… The table's applied settings are being used."] = "Mezclando… Se usan los ajustes aplicados de la tabla.", ["Move a rule up or down by one position."] = "Mueva una regla una posición hacia arriba o hacia abajo.", ["Movies do not belong to a series season."] = "Las películas no pertenecen a una temporada de serie.",
        ["Name a recipe containing 1–8 steps."] = "Dé nombre a una receta de 1 a 8 pasos.", ["Name the Focus view."] = "Ponga nombre a la vista de Focus.", ["Names cannot contain the editor delimiter |."] = "Los nombres no pueden contener el delimitador del editor |.", ["Native DSD uses complete packed-byte frames."] = "El DSD nativo usa fotogramas completos de bytes empaquetados.", ["Native engine unavailable."] = "Motor nativo no disponible.", ["Neutral picture active."] = "Imagen neutra activa.",
        ["New declarative script copy exported."] = "Copia del script declarativo exportada.", ["New excerpt saved. The source was preserved."] = "Fragmento nuevo guardado. La fuente se conservó.", ["New playlist copy saved."] = "Copia de la lista guardada.", ["No EBU loudness measurements were returned."] = "No se devolvió ninguna medición de sonoridad EBU.", ["No analysis runs automatically. Frequencies above approximately 5.5 kHz are excluded by this bounded analysis format."] = "Ningún análisis se ejecuta automáticamente. Este formato de análisis acotado excluye las frecuencias por encima de unos 5,5 kHz.",
        ["No audio-only format was returned."] = "No se devolvió ningún formato solo de audio.", ["No complete file was returned within the download limit."] = "No se devolvió ningún archivo completo dentro del límite de descarga.", ["No external connection is opened until Connect. Parameters are advanced API data, never shell commands."] = "No se abre ninguna conexión externa hasta pulsar Conectar. Los parámetros son datos avanzados de la API, nunca comandos de shell.", ["No frame-average luminance measurements were returned."] = "No se devolvió ninguna medición de luminancia media por fotograma.",
        ["No limiter or automatic safety normalization. Positive gains and summed routes may clip integer output. Two-source mixing ends at the shorter source. Bass management is an electrical crossover, not room calibration or certified acoustic alignment. Double-precision stages are requested before final PCM quantization."] = "Sin limitador ni normalización de seguridad automática. Las ganancias positivas y las rutas sumadas pueden recortar la salida entera. La mezcla de dos fuentes termina en la más corta. La gestión de graves es un cruce eléctrico, no una calibración de sala ni una alineación acústica certificada. Se piden etapas de doble precisión antes de la cuantización PCM final.",
        ["No network request runs until Connect / inspect. Read and remote-change actions remain separate."] = "Ninguna petición de red se ejecuta hasta pulsar Conectar / inspeccionar. Las acciones de lectura y de cambio remoto siguen separadas.", ["No process or IPC listener is created until Start alternate session. Install mpv separately and choose its trusted executable."] = "No se crea ningún proceso ni servicio de escucha IPC hasta pulsar Iniciar la sesión alternativa. Instale mpv aparte y elija su ejecutable de confianza.", ["No saved edit for this source."] = "No hay ninguna edición guardada para esta fuente.",
        ["No supported text subtitle cues were found."] = "No se encontraron subtítulos de texto admitidos.", ["No unambiguous occurrence was found within fifteen days."] = "No se encontró ninguna aparición inequívoca en quince días.", ["None of this session's sources are available."] = "Ninguna de las fuentes de esta sesión está disponible.", ["Not enough ASIO output channels."] = "No hay suficientes canales de salida ASIO.", ["Null catalog entry."] = "Entrada de catálogo nula.", ["Number outside the allowed range"] = "Número fuera del rango permitido",
        ["Numeric argument outside its bounds."] = "Argumento numérico fuera de sus límites.", ["Numeric rules require equality or a numeric bound."] = "Las reglas numéricas requieren igualdad o un límite numérico.", ["OCR did not return bounded text."] = "El OCR no devolvió texto acotado.", ["OPML documents are limited to 4 MiB."] = "Los documentos OPML están limitados a 4 MiB.",
        ["One start/end pair per line; for example: 12.5 18.0. Empty Ordered segments plays the source normally with optional skips/mutes. Native A–B looping and intro/outro rules take precedence."] = "Un par inicio/fin por línea; por ejemplo: 12.5 18.0. Con Segmentos ordenados vacío, la fuente se reproduce con normalidad con omisiones o silencios opcionales. El bucle A–B nativo y las reglas de introducción y final tienen prioridad.", ["Only JPEG/PNG cover copies are accepted."] = "Solo se aceptan copias de portada JPEG/PNG.", ["Only one byte range is supported."] = "Solo se admite un rango de bytes.",
        ["Open 1–5,000 photos."] = "Abra de 1 a 5 000 fotos.", ["Open SRT/WebVTT subtitles. Quality reviews flag candidates; document edits remain in memory until exported."] = "Abra subtítulos SRT/WebVTT. Las revisiones de calidad señalan candidatos; las ediciones del documento quedan en memoria hasta que se exporten.", ["Open a CUE document first so relative references have a base folder."] = "Abra antes un documento CUE para que las referencias relativas tengan una carpeta base.", ["Open a collection first."] = "Abra antes una colección.", ["Open a local media file first."] = "Abra antes un archivo multimedia local.",
        ["Open a local video for file-hash matching, or turn hash matching off."] = "Abra un vídeo local para comparar por huella, o desactive la comparación por huella.", ["Open a video and choose zoom 1–8 with pan in −1…1."] = "Abra un vídeo y elija un zoom de 1 a 8 con un desplazamiento de −1 a 1.", ["Open a video and use an offset within ten minutes."] = "Abra un vídeo y use un desfase de menos de diez minutos.", ["Open an album or playlist, then select tracks."] = "Abra un álbum o una lista y elija después las pistas.", ["Open an output first."] = "Abra antes una salida.",
        ["Open media before applying session lyrics."] = "Abra un archivo antes de aplicar la letra de la sesión.", ["Open media before inserting its current position."] = "Abra un archivo antes de insertar su posición actual.", ["Open the ASIO driver first."] = "Abra antes el controlador ASIO.", ["Open the intended track first."] = "Abra antes la pista que corresponda.", ["Open the unchanged source for this edit first."] = "Abra antes la fuente sin cambios de esta edición.", ["Open this recipe in the matching audio/video category."] = "Abra esta receta en la categoría de audio o vídeo que le corresponda.", ["Open video or select Video mode before entering fullscreen."] = "Abra un vídeo o elija el modo Vídeo antes de pasar a pantalla completa.",
        ["Opened a session relay URL. Closing/reconnecting ends its availability; upstream token is not stored in the queue."] = "Se abrió una URL de retransmisión de la sesión. Al cerrar o reconectar deja de estar disponible; el token de origen no se guarda en la cola.", ["Opened the cached local copy; ETag revalidation was requested when available."] = "Se abrió la copia local en caché; se solicitó la revalidación por ETag cuando estaba disponible.", ["Opened the selected temporary URL; separate video-only tracks do not include audio. Some providers require headers unsupported by direct playback."] = "Se abrió la URL temporal elegida; las pistas solo de vídeo no incluyen audio. Algunos proveedores requieren cabeceras que la reproducción directa no admite.",
        ["Option staged for the next mpv launch in this panel. Close and restart the session to apply it."] = "Opción preparada para el próximo inicio de mpv en este panel. Cierre y reinicie la sesión para aplicarla.", ["Options changed. Preview again before applying."] = "Las opciones cambiaron. Vuelva a ver la vista previa antes de aplicar.", ["Ordered duration chapters require valid end times after their starts."] = "Los capítulos de duración ordenada requieren tiempos de fin válidos posteriores a sus inicios.", ["Ordered or linked-segment chapters require container playback support and cannot be attached to one timeline."] = "Los capítulos ordenados o de segmentos enlazados requieren que el contenedor admita su reproducción y no se pueden unir en una sola línea de tiempo.",
        ["Organization moves support the same drive/share only. Cross-drive copying is not part of this tool."] = "Los movimientos de organización solo admiten la misma unidad o recurso compartido. Copiar entre unidades no forma parte de esta herramienta.", ["Organizing supports local filesystem sources only."] = "La organización solo admite fuentes del sistema de archivos local.", ["Output: first video and optional first audio stream, no subtitles/additional tracks. HDR conversion requires zscale/tonemap in FFmpeg. Target nits do not change the physical monitor. Existing files are preserved."] = "Salida: el primer flujo de vídeo y, opcionalmente, el primero de audio, sin subtítulos ni pistas adicionales. La conversión HDR requiere zscale/tonemap en FFmpeg. Los nits objetivo no cambian el monitor físico. Los archivos existentes se conservan.",
        ["Owned mpv session started idle and paused. Choose Open local media or Open URL, then Pause/resume. Main playback remains independent."] = "Sesión de mpv propia iniciada en reposo y en pausa. Elija Abrir medios locales o Abrir URL y luego Pausar / reanudar. La reproducción principal sigue siendo independiente.", ["Owned session closed. Staged startup choices are retained in this panel for the next explicit launch."] = "Sesión propia cerrada. Las opciones de inicio preparadas se conservan en este panel para el próximo inicio explícito.", ["Plain MPD is allowed only on loopback. Use a certificate-validating TLS proxy for remote connections."] = "MPD sin cifrar solo se permite en bucle local. Use un proxy TLS que valide certificados para las conexiones remotas.",
        ["Play this source before capturing its current position."] = "Reproduzca esta fuente antes de capturar su posición actual.", ["Playback history exceeds 32 MiB."] = "El historial de reproducción supera los 32 MiB.", ["Playback history is empty."] = "El historial de reproducción está vacío.", ["Playback history is not valid JSON. The existing file was preserved."] = "El historial de reproducción no es un JSON válido. El archivo existente se conservó.", ["Playback leaves need valid start/end times."] = "Las hojas de reproducción necesitan tiempos de inicio y fin válidos.", ["Playing ordered chapter steps. Manual source changes or Stop cancel the edition."] = "Reproduciendo pasos de capítulos ordenados. Un cambio de fuente manual o Detener cancelan la edición.",
        ["Playing through a session-only authenticated relay."] = "Reproduciendo mediante una retransmisión autenticada solo para esta sesión.", ["Playlist order changed. Read its occurrences again and review the positions."] = "El orden de la lista cambió. Lea de nuevo sus apariciones y revise las posiciones.", ["Positions were sampled sequentially. Drift is relative to the first playing zone, not a calibrated output-clock measurement."] = "Las posiciones se muestrearon de forma secuencial. La deriva es relativa a la primera zona en reproducción, no una medición calibrada del reloj de salida.", ["Preferences could not be saved"] = "No se pudieron guardar las preferencias", ["Preferences saved and applied."] = "Preferencias guardadas y aplicadas.", ["Prepare first."] = "Prepare primero."
    };
}
